mapper.select:
SELECT pp.id,pp.create_user_id AS createUserId, pp.create_user_name AS createUserName, pp.create_time AS createTime, pp.product_id AS productId, pi.name AS productName, pp.type,pp.phase, pp.approval_finish_time AS approvalFinishTime, pp.status,pp.task_quantity AS taskQuantity, pp.remark FROM project_plan PP LEFT JOIN product_info pi ON PP.product_id =pi.id AND pi.is_deleted = FALSE WHERE PP.is_deleted=false
AND pi.name LIKE concat('%',#{params.searchKeyword},'%')
AND pp.id IN
#{id}
AND pp.status IN
#{status}
${params.permissionSql }
ORDER BY
${item.field} ${item.sort}
pp.create_time DESC
